        "trigger": "시장 변동성",
        "budgetItem": "비R&D 금융·판로 사업으로 구매확약, 보증, 레퍼런스 확보를 묶어 민간 투자 공백을 완화",
        "why": "AI·반도체 주가 변동성이 커지면 비상장 팹리스의 투자 유치와 고객 PoC가 동시에 지연될 수 있습니다.",
        "kpi": "구매확약 금액, 보증 연계 금액, 후속 투자 유치, 고용 유지",
