        "budgetItem": "5개 NPU 기업의 제품을 공공·민간 수요자가 직접 비교 체험할 수 있는 상설 데모룸과 온라인 쇼케이스 운영",
        "why": "비R&D 사업은 수요자가 실제 성능과 적용 시나리오를 이해하도록 만드는 접점이 중요합니다.",
        "kpi": "방문 수요기관 수, 데모 신청 건수, 후속 상담 건수, PoC 전환율",
